161	      record(payload.orgId, "project.archived", {
162	        actorId: payload.actorId,
163	        subjectKind: "project",
164	        subjectId: payload.projectId,
165	        projectId: payload.projectId,
166	        summary: `Archived project with ${payload.issuesArchived} issues`,
167	      }).then(() => undefined),
168	    ),
169	    subscribe("issue.created", (payload) =>
170	      record(payload.orgId, "issue.created", {
171	        actorId: payload.actorId,
172	        subjectKind: "issue",
173	        subjectId: payload.issueId,
174	        projectId: payload.projectId,
175	        summary: `Created issue "${payload.title}"`,
176	        metadata: { priority: payload.priority },
177	      }).then(() => undefined),
178	    ),
179	    subscribe("issue.status_changed", (payload) =>
180	      record(payload.orgId, "issue.status_changed", {
181	        actorId: payload.actorId,
182	        subjectKind: "issue",
183	        subjectId: payload.issueId,
184	        projectId: payload.projectId,
185	        summary: `Status ${payload.from} → ${payload.to}`,
186	        metadata: { from: payload.from, to: payload.to },
187	      }).then(() => undefined),
188	    ),
189	    subscribe("issue.assigned", (payload) =>
190	      record(payload.orgId, "issue.assigned", {
191	        actorId: payload.actorId,
192	        subjectKind: "issue",
193	        subjectId: payload.issueId,
194	        projectId: payload.projectId,
195	        summary: `Assigned to ${payload.assigneeId}`,
196	      }).then(() => undefined),
197	    ),
198	    subscribe("comment.created", (payload) =>
199	      record(payload.orgId, "comment.created", {
200	        actorId: payload.actorId,
201	        subjectKind: "comment",
202	        subjectId: payload.commentId,
203	        projectId: null,
